# Let's read the uploaded files for internal reasoning.
paths = ["/mnt/data/LEAN_MODE.md", "/mnt/data/WORKFLOW.md", "/mnt/data/Overseer.txt", "/mnt/data/Iterator .txt"]
contents = {}
for p in paths:
    try:
        with open(p, 'r', encoding='utf-8') as f:
            contents[p] = f.read()
    except Exception as e:
        contents[p] = f"ERROR: {e}"
contents

